/* Qidian V8 compact feature decoder; Adobe Source Han Sans reference features, SIL OFL 1.1. */
function QDLoadModel(encoded) {
  var raw=atob(encoded), buf=new ArrayBuffer(raw.length), bytes=new Uint8Array(buf);
  for(var i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
  var h=new Uint32Array(buf,0,8), dims=h[1],count=h[2],clusters=h[3],sub=h[4],width=h[5],codes=h[6],pos=32;
  if(h[0]!==0x51444638||dims!==96||sub!==16||width!==6||codes!==256)throw new Error('字形参考数据损坏');
  var bias=new Float32Array(buf,pos,dims);pos+=dims*4;
  function quantized(n){var gain=new DataView(buf).getFloat32(pos,true);pos+=4;var data=new Int16Array(buf,pos,n);pos+=n*2;var values=new Float32Array(n);for(var j=0;j<n;j++)values[j]=data[j]*gain;return values;}
  var basis=quantized(dims*1024),centers=quantized(clusters*dims),books=quantized(sub*codes*width);
  var offsets=new Uint32Array(buf,pos,clusters+1);pos+=(clusters+1)*4;
  var labels=new Uint16Array(buf,pos,count);pos+=count*2;
  var values=new Uint8Array(buf,pos,count*sub);pos+=count*sub;pos=(pos+3)&~3;
  var normGain=new DataView(buf).getFloat32(pos,true);pos+=4;
  var errors=new Uint16Array(buf,pos,count);
  return function classify(v){
    var q=new Float32Array(dims),j,k,x,d,score;
    for(j=0;j<dims;j++){x=-bias[j];for(k=0;k<1024;k++)x+=basis[j*1024+k]*v[k];q[j]=x;}
    var selected=[];
    for(j=0;j<clusters;j++){score=0;for(k=0;k<dims;k++){d=q[k]-centers[j*dims+k];score+=d*d;}selected.push({id:j,score:score});}
    selected.sort(function(a,b){return a.score-b.score;});
    var lut=new Float32Array(sub*codes),best=Infinity,second=Infinity,label=0,bestIndex=0;
    for(var group=0;group<12;group++){var id=selected[group].id;
      for(j=0;j<sub;j++)for(k=0;k<codes;k++){score=0;for(var f=0;f<width;f++){d=q[j*width+f]-centers[id*dims+j*width+f]-books[(j*codes+k)*width+f];score+=d*d;}lut[j*codes+k]=score;}
      for(j=offsets[id];j<offsets[id+1];j++){
        score=0;for(k=0;k<sub;k++){score+=lut[k*codes+values[j*sub+k]];if(score>second)break;}
        if(labels[j]===label){if(score<best){best=score;bestIndex=j;}}
        else if(score<best){second=best;best=score;label=labels[j];bestIndex=j;}
        else if(score<second)second=score;
      }
    }
    return {char:String.fromCharCode(label),score:Math.max(0,best-errors[bestIndex]*normGain)/1024,gap:(second-best)/1024};
  };
}
function QDGlyphVector(makeCanvas, character, family, mirrored) {
  var canvas = makeCanvas(128,128), ctx = canvas.getContext('2d');
  ctx.font = 'normal 400 96px ' + family; ctx.textBaseline = 'alphabetic';
  var m = ctx.measureText(character);
  var width = Math.ceil(m.actualBoundingBoxLeft + m.actualBoundingBoxRight) + 8;
  var height = Math.ceil(m.actualBoundingBoxAscent + m.actualBoundingBoxDescent) + 8;
  if (!(width > 8 && height > 8) || width > 512 || height > 512) throw new Error('字形尺寸异常');
  canvas.width = width; canvas.height = height; ctx = canvas.getContext('2d');
  ctx.font = 'normal 400 96px ' + family; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = '#fff';
  ctx.fillText(character, 4 + m.actualBoundingBoxLeft, 4 + m.actualBoundingBoxAscent);
  var pixels = ctx.getImageData(0,0,width,height).data, left=width, top=height, right=-1, bottom=-1;
  for (var y=0; y<height; y++) for (var x=0; x<width; x++) if (pixels[(y*width+x)*4+3]) {
    if(x<left)left=x; if(x>right)right=x; if(y<top)top=y; if(y>bottom)bottom=y;
  }
  if (right < left || bottom < top) throw new Error('字形尚未加载');
  var small = makeCanvas(32,32), out = small.getContext('2d');
  out.imageSmoothingEnabled = true; out.imageSmoothingQuality = 'high';
  if (mirrored) {out.translate(32,0);out.scale(-1,1);}
  out.drawImage(canvas,left,top,right-left+1,bottom-top+1,0,0,32,32);
  var data = out.getImageData(0,0,32,32).data, vector = new Float32Array(1024);
  for (var i=0; i<1024; i++) vector[i]=data[i*4+3]/255;
  return vector;
}
if (typeof module !== 'undefined') module.exports = { QDLoadModel:QDLoadModel, QDGlyphVector:QDGlyphVector };
function QDCoverage(buffer) {
  var data = new DataView(buffer), result = new Uint8Array(0x110000);
  var table = -1, tables = data.getUint16(4), i, j;
  for(i=0;i<tables;i++){var p=12+i*16;if(data.getUint32(p)===0x636d6170)table=data.getUint32(p+8);}
  if(table<0)throw new Error('本章字体缺少字符映射表');
  var count=data.getUint16(table+2);
  for(i=0;i<count;i++) {
    var rec=table+4+i*8, platform=data.getUint16(rec), encoding=data.getUint16(rec+2);
    if(platform!==0 && !(platform===3&&(encoding===1||encoding===10)))continue;
    var sub=table+data.getUint32(rec+4), format=data.getUint16(sub);
    if(format===4){
      var segments=data.getUint16(sub+6)/2,end=sub+14,start=end+2*segments+2,delta=start+2*segments,offset=delta+2*segments;
      for(j=0;j<segments;j++)for(var code=data.getUint16(start+j*2),last=data.getUint16(end+j*2);code<=last;code++){
        var ro=data.getUint16(offset+j*2), glyph;
        if(ro){glyph=data.getUint16(offset+j*2+ro+(code-data.getUint16(start+j*2))*2);if(glyph)glyph=(glyph+data.getInt16(delta+j*2))&65535;}
        else glyph=(code+data.getInt16(delta+j*2))&65535;
        if(glyph)result[code]=1;
      }
