        url: url,
        style: {
            layout_flexGrow: type1,
            layout_flexBasisPercent: type2
        }
    });
};
var sites = [{
        u: "http://m.duzhige.com/sort/",
        ti: "༺ˇ»`类型分类´«ˇ༻",
        se: "ul.menu_nav > li > a"
    },
    {
        u: "http://m.duzhige.com/yuedutop_allvisit_1.html",
        ti: "༺ˇ»`排行分类´«ˇ༻",
        se: "ul.ranking_list > li > p > a"
    }];
for (var site of sites) {
    var o = org.jsoup.Jsoup.parse(java.ajax(site.u));
    var s = o.select(site.se);
    push(site.ti,"","1","1");
    for (var i = 0; i < s.size(); i++) {
        var urls = String(s[i].attr("href")).replace(/(.*)_(\d+)\.html/,"$1_{{page}}.html");
        push(s[i].text(), urls, "1", "0.25")
    }
};
push("最新小说","/yueduallbook_{{page}}.html","1","0.4");
push("全本小说","/yuedufull_{{page}}.html","1","0.4")
JSON.stringify(sort);

